    final lines = <String>[];
    for (final record in fresh) {
      final snapshot = _builder.append(record);
      while (_rendered < snapshot.records.length) {
        lines.add(_trajectoryLine(snapshot.records[_rendered], width));
        _rendered++;
      }
    }
    return lines;
  }
}

