/// `…` notice naming the hidden count. Empty snapshot → `['no records']`.
List<String> trajectoryLines(
  TrajectorySnapshot snapshot, {
  int width = 80,
  int maxLines = trajectoryMaxLines,
}) {
  if (snapshot.records.isEmpty) return const ['no records'];
